-- CreateTable
CREATE TABLE "policy_versions" (
    "id" TEXT NOT NULL,
    "published_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "current" BOOLEAN NOT NULL DEFAULT false,
    "documents" JSONB NOT NULL,

    CONSTRAINT "policy_versions_pkey" PRIMARY KEY ("id")
);

-- Solo una version puede estar vigente.
CREATE UNIQUE INDEX "policy_versions_current_key" ON "policy_versions"("current") WHERE "current";

-- La version que ya estaba en el codigo y las que ya aceptaron los usuarios.
-- Los textos que estaban en apps/mobile/lib/legal (usos, privacidad y baja de cuenta).
INSERT INTO "policy_versions" ("id", "published_at", "current", "documents")
VALUES ('2026-11-12', '2026-11-12T00:00:00Z', true, $json${"terms":{"title":"Políticas de uso","intro":"Estas políticas rigen el uso de potrero, la app para organizar torneos de fútbol amateur. Al crear una cuenta, la persona declara que las leyó y las acepta. La aceptación queda registrada con su fecha y versión.","sections":[{"heading":"1. Quiénes usan potrero","blocks":[["Visitantes: ven torneos, tablas, fixture y perfiles sin cuenta.","Usuarios con cuenta: juegan, forman equipos, organizan torneos o arbitran, según su rol.","Admin: el equipo de potrero, que aprueba organizadores y puede dar de baja usuarios, torneos o sponsors."]]},{"heading":"2. Reglas para todas las cuentas","blocks":[["Cada persona tiene una sola cuenta, con sus datos reales.","Para inscribirse en un plantel, organizar o cobrar, la persona verifica su identidad con DNI y selfie. Sin identidad verificada no se puede integrar un plantel ni jugar un partido.","Las cuentas no se prestan ni se venden.","No se puede suplantar a otra persona, ni usar fotos o datos de terceros como propios.","No se puede cargar información falsa: resultados, tarjetas, pagos o comprobantes.","Se trata con respeto a jugadores, árbitros, organizadores y al resto de las personas. No se admiten insultos, amenazas ni discriminación, tampoco en reseñas o en la foto de perfil.","No se puede usar potrero para otra cosa que organizar o seguir torneos amateur, ni intentar acceder a datos de otras personas."]]},{"heading":"3. Reglas de los torneos","blocks":[["La inscripción de un equipo es gratuita. El organizador cobra una cuota por fecha a cada equipo.","Una fecha impaga no impide jugarla, pero la cuota pasa a vencida y se suma una multa fija, definida por el torneo.","Un equipo con una fecha anterior vencida solo puede perder por walkover (3-0 en contra).","Dos fechas seguidas impagas dan de baja al equipo. Sus partidos ya jugados se mantienen y los pendientes se cancelan.","La deuda de un equipo dado de baja sigue siendo exigible por el organizador.","Saldar la deuda vuelve a habilitar al equipo, mientras no haya sido dado de baja.","Los resultados los carga el árbitro y el organizador puede corregirlos. Las estadísticas salen solo de los resultados cargados."],"Los pagos entre equipos y organizadores se hacen fuera de potrero, en efectivo o por transferencia. potrero registra lo que se informa y lo que el organizador confirma, pero no cobra ni garantiza ningún pago."]},{"heading":"4. Organizadores, árbitros y sponsors","blocks":[["Para organizar torneos hay que pedir la aprobación del admin, con verificación de identidad. Un organizador no puede jugar en torneos.","El árbitro entra con el link de invitación de un organizador.","Cualquier usuario verificado puede proponer un sponsor para un torneo. El admin lo aprueba o rechaza. Solo puede haber un sponsor principal por torneo. No se aceptan sponsors de alcohol para menores, juegos de azar, contenido ilegal ni marcas que el sponsor no tenga derecho a usar."]]},{"heading":"5. Causas de baja de una cuenta, un torneo o un sponsor","blocks":["El admin puede dar de baja una cuenta, un torneo o un sponsor cuando:",["Se verifica que la persona usa una identidad falsa o ajena, o tiene más de una cuenta.","Se carga información falsa a propósito: resultados, pagos, comprobantes o documentos.","Hay acoso, amenazas, discriminación u otro maltrato, dentro de la app o en el contexto de un torneo.","Se publica contenido ilegal, ofensivo o que viola derechos de terceros, incluidas fotos, escudos, logos y reseñas.","Se intenta acceder a datos ajenos, alterar la app o evadir sus reglas.","Un organizador cobra y no cumple lo que prometió, o deja un torneo sin resolver tras reclamos fundados.","Un sponsor incumple las condiciones de la sección 4."],"Lo dado de baja deja de mostrarse públicamente. Quien fue dado de baja recibe el motivo. Los partidos jugados, los resultados y las deudas se conservan, porque forman parte del historial de otras personas. Una cuenta dada de baja no puede volver a crearse con la misma identidad sin que el admin lo autorice.","La baja de un equipo por falta de pago (sección 3) es automática y no pasa por el admin."]},{"heading":"6. Cambios","blocks":["Las políticas pueden cambiar. Cuando cambien de forma importante, la app avisa y pide aceptar la nueva versión. Seguir usando potrero sin aceptarla no es posible."]},{"heading":"7. Contacto","blocks":["Para consultas o reclamos: [mail de contacto]."]}]},"privacy":{"title":"Política de privacidad","intro":"Esta política explica qué datos personales trata potrero, para qué y qué derechos tiene cada persona. Se rige por la Ley 25.326 de Protección de los Datos Personales de la República Argentina. Responsable del tratamiento: [nombre y domicilio del responsable]. Contacto: [mail de contacto].","sections":[{"heading":"1. Qué datos tratamos","blocks":[["Nombre, mail o cuenta de Google: para identificar la cuenta y mostrar el nombre en torneos y perfiles.","Foto de perfil: para mostrar al jugador en su perfil y en los planteles. Es pública: la ve cualquiera, incluso sin cuenta.","Región: para filtrar torneos y equipos de la zona.","Rol, equipos y torneos en los que participa: para armar planteles, fixture y tablas.","Resultados, goles y tarjetas: los cargan el árbitro o el organizador, para mostrar la tabla, las estadísticas y el historial.","Cuotas, multas, pagos informados, método de pago y comprobantes: para llevar la cuenta de lo que debe cada equipo.","Reseñas y calificaciones: para mostrar la reputación dentro de la app.","Datos del dispositivo para notificaciones: para avisar fixture, pagos, postulaciones y resultados.","Aceptación de políticas (fecha y versión): para dejar constancia de lo aceptado.","Datos de verificación de identidad: ver la sección 2."],"No pedimos domicilio, teléfono ni datos de tarjetas. Los pagos se hacen fuera de potrero."]},{"heading":"2. Verificación de identidad: DNI y selfie","blocks":["Para integrar un plantel, organizar o cobrar, la persona verifica su identidad con una foto del DNI y una selfie.",["La verificación la hace un servicio externo [proveedor a confirmar]. La app le envía las imágenes en el momento y el servicio las compara y devuelve el resultado.","potrero no guarda las fotos del DNI ni de la selfie de la verificación.","Solo guardamos los últimos 4 dígitos del DNI, si la verificación fue aprobada, cuándo, y el identificador de la sesión del proveedor. El número completo no se guarda.","La comparación de la selfie con el documento usa datos biométricos, que son sensibles. Por eso pedimos el consentimiento expreso de la persona, separado de la aceptación general, antes de empezar.","La selfie que la persona elige como foto de perfil se guarda como cualquier otra foto de perfil y es pública. Se le avisa antes de usarla.","El proveedor puede conservar las imágenes por un plazo propio. Configuramos el plazo más corto que permita [a confirmar con el proveedor]."]]},{"heading":"3. Con quién compartimos datos","blocks":["Usamos proveedores que tratan datos por nuestra cuenta, solo para hacer funcionar potrero:",["Supabase: base de datos, inicio de sesión y almacenamiento de fotos.","Railway: servidor de la API.","Expo: publicación de la web, actualizaciones de la app y notificaciones.","Google: inicio de sesión con Google.","[Proveedor de verificación]: verificación de identidad."],"Algunos están en el exterior, así que los datos pueden transferirse fuera de Argentina. No vendemos datos ni los usamos para publicidad.","Cualquier visitante ve torneos, tablas, fixture y perfiles de jugadores: nombre, foto, equipo y estadísticas. Los organizadores de un torneo ven los pagos y comprobantes de los equipos de ese torneo. Nadie más ve el mail ni los datos de verificación."]},{"heading":"4. Cuánto tiempo guardamos los datos","blocks":[["Mientras la cuenta esté activa.","Los resultados y estadísticas de un torneo se conservan mientras sean parte del historial de los demás participantes.","Las deudas pendientes de un equipo se conservan hasta saldarse, aunque el equipo haya sido dado de baja.","Cuando se borra la cuenta, se aplica la sección 5."]]},{"heading":"5. Derechos y borrado de la cuenta","blocks":["Cada persona tiene derecho a acceder a sus datos, rectificarlos y pedir su supresión. La app permite editar el perfil y borrar la cuenta desde la configuración. También se puede pedir por mail a [mail de contacto]. Los detalles están en la página de eliminación de cuenta: /delete-account.","La Agencia de Acceso a la Información Pública es el órgano de control de la Ley 25.326 y recibe las denuncias por incumplimiento: https://www.argentina.gob.ar/aaip"]},{"heading":"6. Seguridad","blocks":["Las fotos y los datos se guardan en servicios con acceso restringido. Cada usuario solo puede subir o borrar sus propios archivos. La base de datos solo es accesible a través de la API. Ningún sistema es infalible: si hay un incidente que afecte datos personales, lo comunicamos a las personas afectadas."]},{"heading":"7. Menores de edad","blocks":["[El equipo define la edad mínima para tener cuenta y si se necesita autorización de un adulto.]"]},{"heading":"8. Cambios","blocks":["Si esta política cambia de forma importante, la app avisa y pide aceptar la nueva versión. Versión: [fecha de publicación]."]}]},"accountDeletion":{"title":"Eliminar la cuenta","intro":"Cada persona puede pedir que se borre su cuenta de potrero y los datos personales asociados. Esta página explica cómo hacerlo y qué pasa con los datos.","sections":[{"heading":"Cómo pedir el borrado","blocks":[["Desde la app: Configuración, Eliminar cuenta.","Sin la app: escribí a [mail de contacto] desde el mail de tu cuenta, con el asunto \"Eliminar cuenta\". Verificamos que sea tu cuenta y la borramos."]]},{"heading":"Qué se elimina","blocks":[["El mail, el nombre y la foto de perfil.","Los datos de verificación de identidad, incluidos los últimos 4 dígitos del DNI.","Tu lugar en equipos y en los planteles de torneos todavía abiertos.","Los datos del dispositivo para notificaciones."]]},{"heading":"Qué se conserva","blocks":[["Tus partidos, goles y tarjetas de torneos ya jugados, sin tu nombre: aparecen como jugador eliminado, para que no cambien los resultados de otras personas.","Tus reseñas, sin tu nombre.","Si dejaste una deuda con un equipo u organizador, el registro de esa deuda sin datos personales, hasta que se salde."]]},{"heading":"Más información","blocks":["Mirá la política de privacidad en /privacy para saber cómo tratamos los datos."]}]}}$json$::jsonb);

INSERT INTO "policy_versions" ("id", "current", "documents")
SELECT DISTINCT "policies_version", false, (SELECT "documents" FROM "policy_versions" WHERE "id" = '2026-11-12') FROM "users"
WHERE "policies_version" IS NOT NULL AND "policies_version" <> '2026-11-12';

-- AddForeignKey
ALTER TABLE "users" ADD CONSTRAINT "users_policies_version_fkey" FOREIGN KEY ("policies_version") REFERENCES "policy_versions"("id") ON DELETE SET NULL ON UPDATE CASCADE;

ALTER TABLE "policy_versions" ENABLE ROW LEVEL SECURITY;
